WITH RankedPosts AS (SELECT p.Id AS PostId, p.Title, p.CreationDate, p.ViewCount, p.Score, ROW_NUMBER() OVER (PARTITION BY p.OwnerUserId ORDER BY p.CreationDate DESC NULLS FIRST) AS PostRank, p.OwnerUserId FROM Posts AS p WHERE p.CreationDate >= CAST('2024-10-01 12:34:56' AS Nullable(DateTime)) - INTERVAL '1' YEAR), UserBadges AS (SELECT b.UserId, COUNT(b.Id) AS BadgeCount, GROUP_CONCAT(b.Name, ', ') AS BadgeNames FROM Badges AS b GROUP BY b.UserId), PostVotes AS (SELECT v.PostId, SUM(CASE WHEN v.VoteTypeId = 2 THEN 1 ELSE 0 END) AS UpVotes, SUM(CASE WHEN v.VoteTypeId = 3 THEN 1 ELSE 0 END) AS DownVotes FROM Votes AS v GROUP BY v.PostId), UserStatistics AS (SELECT u.Id AS UserId, u.DisplayName, COALESCE(ub.BadgeCount, 0) AS BadgeCount, COALESCE(rb.TopPostCount, 0) AS TopPostCount FROM Users AS u LEFT JOIN UserBadges AS ub ON u.Id = ub.UserId LEFT JOIN (SELECT rp.OwnerUserId, COUNT(*) AS TopPostCount FROM RankedPosts AS rp WHERE rp.PostRank = 1 GROUP BY rp.OwnerUserId) AS rb ON u.Id = rb.OwnerUserId) SELECT us.UserId, us.DisplayName, us.BadgeCount, COALESCE(SUM(pv.UpVotes) - SUM(pv.DownVotes), 0) AS NetVotes, COUNT(rp.PostId) AS TotalPosts, MAX(rp.ViewCount) AS MostViewedPost FROM UserStatistics AS us LEFT JOIN RankedPosts AS rp ON us.UserId = rp.OwnerUserId LEFT JOIN PostVotes AS pv ON rp.PostId = pv.PostId WHERE us.BadgeCount > 0 GROUP BY us.UserId, us.DisplayName, us.BadgeCount HAVING COUNT(rp.PostId) > 5 ORDER BY MostViewedPost DESC NULLS FIRST LIMIT 10